import{_ as o,o as t,c as n,a3 as r}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Calendar Google/Outlook sync (1.4.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar Google/Outlook sync (1.4.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/calendar-google-outlook-sync-1-4-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar Google/Outlook sync (1.4.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/calendar-google-outlook-sync-1-4-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/calendar-google-outlook-sync-1-4-0-production-readiness.md","filePath":"deployment/calendar-google-outlook-sync-1-4-0-production-readiness.md","lastUpdated":1791383195000}'),a={name:"deployment/calendar-google-outlook-sync-1-4-0-production-readiness.md"};function d(s,e,c,l,i,g){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="calendar-google-outlook-sync-1-4-0-—-production-readiness-audit" tabindex="-1">Calendar Google/Outlook sync (1.4.0) — Production Readiness Audit <a class="header-anchor" href="#calendar-google-outlook-sync-1-4-0-—-production-readiness-audit" aria-label="Permalink to &quot;Calendar Google/Outlook sync (1.4.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-30</td></tr><tr><td><strong>Re-verified</strong></td><td>2026-09-30 — branch <code>feature/calendar-google-outlook-sync</code> code review; Pest <strong><code>CalendarIntegrationTest</code></strong> (7) + <strong><code>CalendarEventProviderPushTest</code></strong> (6); Playwright <strong><code>calendar-integrations.spec.ts</code></strong> (panel smoke)</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (merge/deploy remaining; live Google/Microsoft OAuth smoke <strong>post-deploy QA</strong>)</td></tr><tr><td><strong>Scope</strong></td><td>Per-user OAuth connect; one-way <strong>EloSync → provider</strong> push for <strong>manual</strong> events only; catalog <strong>calendar 1.3.0 → 1.4.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./calendar">Calendar deployment</a> · <a href="/user-guide/calendar-overview">Overview</a> · <a href="/developer-guide/calendar">Developer guide</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspace admins with <code>calendar.manage_integrations</code> open <strong>Calendar → Sync</strong> to connect <strong>Google Calendar</strong> or <strong>Microsoft Outlook</strong> (platform OAuth apps in env — not per-tenant). When the <strong>organizer</strong> creates, updates, or cancels a <strong>manual</strong> event, <code>CalendarEventSubscriber</code> queues <code>PushCalendarEventToProviderJob</code> on the <strong><code>calendar-sync</code></strong> Horizon queue; provider HTTP failures are logged and <strong>never block</strong> calendar writes.</p><p>Meeting/task/lead/project overlays, named team calendars, and inbound (two-way) sync remain <strong>deferred</strong>.</p><p><strong>Known Phase-1 limitation:</strong> <code>calendar_events.external_provider</code> / <code>external_event_id</code> store a <strong>single</strong> provider mapping. If the organizer connects <strong>both</strong> Google and Microsoft, create may push to both, but update/cancel only reliably targets the last-written mapping — document for operators; dual-connect is supported but not fully symmetric.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> for engineering deploy. Optional follow-up: one real Google + one real Microsoft connect/push smoke per environment.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Per-user connections (<code>calendar_provider_connections</code>); encrypted tokens</td><td><strong>Pass</strong></td></tr><tr><td>Providers <code>google</code> | <code>microsoft</code> via <code>CalendarSyncProviderRegistry</code></td><td><strong>Pass</strong></td></tr><tr><td>OAuth: platform env credentials + fixed callback <code>/api/oauth/calendar-sync/{provider}/callback</code></td><td><strong>Pass</strong></td></tr><tr><td>Integration API gated by <code>calendar.manage_integrations</code> (admin role default)</td><td><strong>Pass</strong></td></tr><tr><td>Push job soft-fail; manual source only; disconnect stops push</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td><code>CALENDAR_SYNC_PROVIDERS_FAKE</code> / provider <code>fake()</code> forced in <code>testing</code>; not for production</td><td><strong>Pass</strong></td></tr><tr><td>Horizon supervisor includes <strong><code>calendar-sync</code></strong> queue</td><td><strong>Pass</strong> (<code>config/horizon.php</code>)</td></tr><tr><td>SPA <strong>Calendar → Sync</strong> panel + Playwright panel smoke</td><td><strong>Pass</strong></td></tr><tr><td>Catalog migrate-only <strong>1.4.0</strong> + <code>calendar.manage_integrations</code> permission migration</td><td><strong>Pass</strong></td></tr><tr><td>Live Google/Microsoft OAuth + provider calendar verify</td><td><strong>Post-deploy QA</strong></td></tr></tbody></table><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — <code>calendar_provider_connections</code>, <code>external_*</code> on <code>calendar_events</code>, permission + catalog → <strong>1.4.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Set platform env: <code>GOOGLE_CALENDAR_*</code>, <code>MICROSOFT_CALENDAR_*</code>, <code>APP_URL</code> (HTTPS), <code>FRONTEND_URL</code>; register callback on each OAuth app (see <a href="./calendar">Calendar deployment</a>).</li><li>Confirm Horizon workers process <strong><code>calendar-sync</code></strong> (push is async).</li><li>Smoke (when OAuth apps available): admin → Calendar → <strong>Sync</strong> → Connect Google → create manual event → event appears in Google Calendar; update title in EloSync → provider event updates; cancel in EloSync → provider event cancelled; Disconnect → new events no longer push.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back catalog bump (<code>down</code> → <strong>1.3.0</strong>) and drop sync migrations after code rollback. Existing manual events and shares <strong>1.3.0</strong> behavior unchanged; provider connections table can be dropped on rollback migration.</p>',13)])])}const m=o(a,[["render",d]]);export{u as __pageData,m as default};
